(362389, 29329, 327, '<td valign="top">On it''s own I like the shot....rust is always kool. I just don''t think it hits the spot for the challenge. Nice work.</td>', 'On it''s own I like the shot....rust is always kool. I just don''t think it hits the spot for the challenge. Nice work.', '2003-07-21 12:35:11.000000', NULL, 1),
(362393, 29715, 327, '<td valign="top">The perspective here is so abstract that it took me a bit to realize these are piano keys. &lt;That is not a bad thing in all cases. Maybe some levels adjustment if you have access to a graphics program.<br/></td>', 'The perspective here is so abstract that it took me a bit to realize these are piano keys. <That is not a bad thing in all cases. Maybe some levels adjustment if you have access to a graphics program.', '2003-07-21 12:37:52.000000', NULL, 1),
(362394, 29584, 327, '<td valign="top">Over exposed baby. Difficult shooting in the bright sunshine. Nice try and great subject for the challenge.</td>', 'Over exposed baby. Difficult shooting in the bright sunshine. Nice try and great subject for the challenge.', '2003-07-21 12:38:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(362396, 29396, 327, '<td valign="top">Creative idea, but I think better light would of improved this shot.</td>', 'Creative idea, but I think better light would of improved this shot.', '2003-07-21 12:39:16.000000', NULL, 1),
(362398, 29713, 327, '<td valign="top">Hum, if you didn''t tell us what it was how would we know?  This is just a centered handle and nothing else. The shot is boring as it stands, there is not a focal point of interest for the eye.  Your idea was good, but you missed the mark. Maybe if you can reshoot this and take the end of the hoe/rake [?] it would add interest.</td>', 'Hum, if you didn''t tell us what it was how would we know?  This is just a centered handle and nothing else. The shot is boring as it stands, there is not a focal point of interest for the eye.  Your idea was good, but you missed the mark. Maybe if you can reshoot this and take the end of the hoe/rake [?] it would add interest.', '2003-07-21 12:42:29.000000', NULL, 1),
