(363141, 29584, 4494, '<td valign="top">Looks more like a Zebra then a baby. :)  You should have zoomed in on the neck and head since that part has the strongest contrast.</td>', 'Looks more like a Zebra then a baby. :)  You should have zoomed in on the neck and head since that part has the strongest contrast.', '2003-07-22 01:35:22.000000', NULL, 1),
(363142, 29775, 9679, '<td valign="top">Good concept and execution. I would like to see more contrast and the bright area on the feather is somewhat distracting.</td>', 'Good concept and execution. I would like to see more contrast and the bright area on the feather is somewhat distracting.', '2003-07-22 01:37:14.000000', NULL, 1),
