(363146, 29506, 9679, '<td valign="top">Wonderful lines really pull me into the picture and make me try to figure out what is real and what is reflection. Very nice! 8</td>', 'Wonderful lines really pull me into the picture and make me try to figure out what is real and what is reflection. Very nice! 8', '2003-07-22 01:41:13.000000', NULL, 1),
(363148, 29768, 9679, '<td valign="top">Great job on the lighting, shadows, detail. 9</td>', 'Great job on the lighting, shadows, detail. 9', '2003-07-22 01:42:15.000000', NULL, 1),
