(363150, 29599, 9679, '<td valign="top">Beautifully done. Very emotive. 8</td>', 'Beautifully done. Very emotive. 8', '2003-07-22 01:44:49.000000', NULL, 1),
(363153, 29745, 9679, '<td valign="top">Who doesn''t like Oreos? :) Nice touch with the partially eaten cookie and I really like the way you set this up. 8</td>', 'Who doesn''t like Oreos? :) Nice touch with the partially eaten cookie and I really like the way you set this up. 8', '2003-07-22 01:48:10.000000', NULL, 1),
(363154, 29746, 5318, '<td valign="top">Great shot soni,HEAVENLY........10</td>', 'Great shot soni,HEAVENLY........10', '2003-07-22 01:52:12.000000', NULL, 1),
(363188, 29578, 10465, '<td valign="top">This is an intriguing image. Excellent contrast, nice mix of textures, very surreal...<br/>This one gets my vote!</td>', 'This is an intriguing image. Excellent contrast, nice mix of textures, very surreal...This one gets my vote!', '2003-07-22 04:07:51.000000', NULL, 1),
(363207, 29769, 9073, '<td valign="top">I''ve just had my 1st baby, so I know how much meaning this shot has for you - there''s a real sense of family here. However, photographically, I feel that it''s important not to forget the basics. Here, the flash caused a few core problems, the harsh shadows and the blue tinges, especially on the white towel, and weak colours in the top right and bottom left. Also, take care about the background. The green doesn''t help at all, the skirting board presents a conflicting line and there''s a thingy hanging down in the top centre.</td>', 'I''ve just had my 1st baby, so I know how much meaning this shot has for you - there''s a real sense of family here. However, photographically, I feel that it''s important not to forget the basics. Here, the flash caused a few core problems, the harsh shadows and the blue tinges, especially on the white towel, and weak colours in the top right and bottom left. Also, take care about the background. The green doesn''t help at all, the skirting board presents a conflicting line and there''s a thingy hanging down in the top centre.', '2003-07-22 04:44:22.000000', NULL, 1),
(363208, 29749, 9073, '<td valign="top">I don''t really think that the crosses are at all necessary here. In fact, I feel that they ruin an otherwise great shot.</td>', 'I don''t really think that the crosses are at all necessary here. In fact, I feel that they ruin an otherwise great shot.', '2003-07-22 04:46:15.000000', NULL, 1),
(363209, 29482, 9073, '<td valign="top">Nice textures here</td>', 'Nice textures here', '2003-07-22 04:49:06.000000', NULL, 1),
(363214, 29775, 5728, '<td valign="top">Beautiful pic, great set up and very contrasty :-) (10)</td>', 'Beautiful pic, great set up and very contrasty :-) (10)', '2003-07-22 05:03:15.000000', NULL, 1),
(363215, 29599, 5728, '<td valign="top">My absolute favourite for the challenge, it''s gotta win! A wonderful depiction of contrast and a beautiful photo. You can be very proud of this pic - 10.</td>', 'My absolute favourite for the challenge, it''s gotta win! A wonderful depiction of contrast and a beautiful photo. You can be very proud of this pic - 10.', '2003-07-22 05:04:45.000000', NULL, 1),
(363216, 28772, 5728, '<td valign="top">Excellent detail and lighting. A wonderful pic in every aspect  - 10.</td>', 'Excellent detail and lighting. A wonderful pic in every aspect  - 10.', '2003-07-22 05:06:31.000000', NULL, 1),
(363217, 29657, 5728, '<td valign="top">Beautiful colors and contrasts. The sun is a little too centered but it doesn''t bother me here - 10.</td>', 'Beautiful colors and contrasts. The sun is a little too centered but it doesn''t bother me here - 10.', '2003-07-22 05:07:12.000000', NULL, 1),
(363218, 29165, 5728, '<td valign="top">Beautiful and soft. Your pic really has a mellow feeling to it. Be proud of yourself with this photo! - 10.</td>', 'Beautiful and soft. Your pic really has a mellow feeling to it. Be proud of yourself with this photo! - 10.', '2003-07-22 05:08:16.000000', NULL, 1),
(363219, 29682, 5728, '<td valign="top">This is so awesome! Amazing colors and contrast, well done - 10.</td>', 'This is so awesome! Amazing colors and contrast, well done - 10.', '2003-07-22 05:08:56.000000', NULL, 1);
