(363235, 29622, 5728, '<td valign="top">Amazing nightshot, I love the angle you got here, choice!</td>', 'Amazing nightshot, I love the angle you got here, choice!', '2003-07-22 06:19:59.000000', NULL, 1),
(363236, 29701, 5728, '<td valign="top">Nice contrast, and an amazing shot - 9.</td>', 'Nice contrast, and an amazing shot - 9.', '2003-07-22 06:20:28.000000', NULL, 1),
(363238, 29453, 5728, '<td valign="top">Good one, I like it a lot. The only thing bothersome is the greens coming out of the snail itself - 9.</td>', 'Good one, I like it a lot. The only thing bothersome is the greens coming out of the snail itself - 9.', '2003-07-22 06:21:30.000000', NULL, 1),
(363239, 29770, 5728, '<td valign="top">Would have done well in the temperature challenge too. This is very good - 9.</td>', 'Would have done well in the temperature challenge too. This is very good - 9.', '2003-07-22 06:22:13.000000', NULL, 1),
