(363264, 29110, 5728, '<td valign="top">Interesting! Meets the challenge for sure, very original too.</td>', 'Interesting! Meets the challenge for sure, very original too.', '2003-07-22 07:52:14.000000', NULL, 1),
(363265, 29444, 5728, '<td valign="top">Very good contrast photo! This was the sort of pic I first thought of when I saw the new challenge topic, well done!</td>', 'Very good contrast photo! This was the sort of pic I first thought of when I saw the new challenge topic, well done!', '2003-07-22 07:53:14.000000', NULL, 1),
(363267, 29584, 5728, '<td valign="top">A zebra, of course, what a good idea for contrast. The background is a little bothersome tho, maybe a shallower DOF or different background would have enhanced this photo.</td>', 'A zebra, of course, what a good idea for contrast. The background is a little bothersome tho, maybe a shallower DOF or different background would have enhanced this photo.', '2003-07-22 07:55:23.000000', NULL, 1),
(363268, 29396, 5728, '<td valign="top">Good idea :-)</td>', 'Good idea :-)', '2003-07-22 07:55:49.000000', NULL, 1),
(363270, 29759, 5728, '<td valign="top">Some major contrast here, good one :-) You got the detail coming out there wonderfully.</td>', 'Some major contrast here, good one :-) You got the detail coming out there wonderfully.', '2003-07-22 07:59:25.000000', NULL, 1),
(363279, 29324, 8637, '<td valign="top">One of the top!  Great shot, beautiful composition, meets the challenge!  thanks</td>', 'One of the top!  Great shot, beautiful composition, meets the challenge!  thanks', '2003-07-22 08:18:33.000000', NULL, 1),
(363280, 29704, 8637, '<td valign="top">Nice shot...and very good compsition.  How did you ever decide which angle to use?  hanks</td>', 'Nice shot...and very good compsition.  How did you ever decide which angle to use?  hanks', '2003-07-22 08:19:22.000000', NULL, 1),
(363291, 29583, 7743, '<td valign="top">Good take on the challenge.  This is a challenging image due to the bright white and solid black bulls.  It also appears that the light is coming from the left therefore adding glare to the white bull.  I wonder if a diffuser would have helped here (probably out of the question though due to the nature of the beasts).<br/> <br/>The DOF is perfect with just a touch of blurred grass in the foreground.<br/></td>', 'Good take on the challenge.  This is a challenging image due to the bright white and solid black bulls.  It also appears that the light is coming from the left therefore adding glare to the white bull.  I wonder if a diffuser would have helped here (probably out of the question though due to the nature of the beasts). The DOF is perfect with just a touch of blurred grass in the foreground.', '2003-07-22 09:17:12.000000', NULL, 1),
(363301, 29594, 8637, '<td valign="top">Not sure I like the B&amp;W as much as I might in color...but like the view and the composition.  thanks</td>', 'Not sure I like the B&W as much as I might in color...but like the view and the composition.  thanks', '2003-07-22 09:30:24.000000', NULL, 1),
(363304, 29767, 8637, '<td valign="top">Too bad you could not "clone" out the white spots for the competition..but very neat shot and excellent "contrast".  thanks</td>', 'Too bad you could not "clone" out the white spots for the competition..but very neat shot and excellent "contrast".  thanks', '2003-07-22 09:31:26.000000', NULL, 1),
(363305, 29453, 8637, '<td valign="top">Now you''re talking...makes me hungry just thinkling about it...super macro and interesting twist on "contrast".  thanks</td>', 'Now you''re talking...makes me hungry just thinkling about it...super macro and interesting twist on "contrast".  thanks', '2003-07-22 09:32:17.000000', NULL, 1),
(363317, 29714, 1202, '<td valign="top">This is one of my favorite subjects, the old and new mix.  I wish your old house had not been quite so centered and flat though.  6</td>', 'This is one of my favorite subjects, the old and new mix.  I wish your old house had not been quite so centered and flat though.  6', '2003-07-22 09:46:52.000000', NULL, 1),
