(363828, 29744, 1202, '<td valign="top">Wonderful, contrasty shot.   Your timing was excellent on this shot.   You have just enough foreground to enhance the beautiful and unsettled cloud formations.   9</td>', 'Wonderful, contrasty shot.   Your timing was excellent on this shot.   You have just enough foreground to enhance the beautiful and unsettled cloud formations.   9', '2003-07-22 20:39:04.000000', NULL, 1),
