(365269, 29715, 7969, '<td valign="top">I am trying to comment on all the photos this challenge, this one i find hard to comment on,  I think it is because nothing really strikes me.  So I guess my comment would be needs a little more wow factor, in subject choice and maybe in  composition.</td>', 'I am trying to comment on all the photos this challenge, this one i find hard to comment on,  I think it is because nothing really strikes me.  So I guess my comment would be needs a little more wow factor, in subject choice and maybe in  composition.', '2003-07-23 19:41:16.000000', NULL, 1),
(365272, 28869, 7969, '<td valign="top">I think this shot needs something to focus on.  I think it is overprocessed a little - the bottom leaves look fake.   I  think I would like to see this shot with just the red wall and the spoon.  just my opinion.</td>', 'I think this shot needs something to focus on.  I think it is overprocessed a little - the bottom leaves look fake.   I  think I would like to see this shot with just the red wall and the spoon.  just my opinion.', '2003-07-23 19:44:01.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(365279, 29396, 7969, '<td valign="top">Well, it reminds me of an inmate i once knew who had this tattooed on his hands in just this fashion.  I am sure there was/is a statement in it, they are two strong , and yes, contrasting  words, but I am left with wondering (as i was with him)... well, but what about them??  As an aside I have come to think indifference is more the opposite of love then hate.   I am not sure my comment helps, maybe this is better way to say it, using words in a photo almost makes you not ''need'' the picture, in a photo I would like to ''see'' those things.  My final feeling is that it is missing something.  And that I am left with a question and feeling I will give you an extra point then planned to, sense I think photos should make you feel.  keep up the efforts.</td>', 'Well, it reminds me of an inmate i once knew who had this tattooed on his hands in just this fashion.  I am sure there was/is a statement in it, they are two strong , and yes, contrasting  words, but I am left with wondering (as i was with him)... well, but what about them??  As an aside I have come to think indifference is more the opposite of love then hate.   I am not sure my comment helps, maybe this is better way to say it, using words in a photo almost makes you not ''need'' the picture, in a photo I would like to ''see'' those things.  My final feeling is that it is missing something.  And that I am left with a question and feeling I will give you an extra point then planned to, sense I think photos should make you feel.  keep up the efforts.', '2003-07-23 19:49:33.000000', NULL, 1),
(365281, 29655, 7969, '<td valign="top">Not sure what the subject is, yes the pond, but still feels like it is missing something,  maybe a turtle or a lily or a bullfrog somewhere.</td>', 'Not sure what the subject is, yes the pond, but still feels like it is missing something,  maybe a turtle or a lily or a bullfrog somewhere.', '2003-07-23 19:51:13.000000', NULL, 1),
(365284, 29320, 7969, '<td valign="top">I like the ripples on the lower green leaf, the red part feels a bit too bright and shot is a bit too centered.  just my opinion.</td>', 'I like the ripples on the lower green leaf, the red part feels a bit too bright and shot is a bit too centered.  just my opinion.', '2003-07-23 19:53:12.000000', NULL, 1),
(365289, 29056, 7969, '<td valign="top">I am trying to comment on all the shots this time, this one is hard, to be honest I did not score it too high, but I think in fairness I need to tell you why.  I think it is nothing screams out at me of interest, the shadow itself I think needs to pushed more-- i.e. darkened or more contrast to make the image stronger.  I also don''t think the bottom shadow does much but to distract from the more interesting crane part.  keep up  the efforts.   (just my opinion)</td>', 'I am trying to comment on all the shots this time, this one is hard, to be honest I did not score it too high, but I think in fairness I need to tell you why.  I think it is nothing screams out at me of interest, the shadow itself I think needs to pushed more-- i.e. darkened or more contrast to make the image stronger.  I also don''t think the bottom shadow does much but to distract from the more interesting crane part.  keep up  the efforts.   (just my opinion)', '2003-07-23 19:57:27.000000', NULL, 1),
(365293, 29580, 7969, '<td valign="top">Would like the dark parts to be a little darker so that the contrast is stronger.  I think in a patterned shot like this there needs to be something that ''grabs'' the viewer, not sure if this one does,  sorry just my opinion.</td>', 'Would like the dark parts to be a little darker so that the contrast is stronger.  I think in a patterned shot like this there needs to be something that ''grabs'' the viewer, not sure if this one does,  sorry just my opinion.', '2003-07-23 19:59:20.000000', NULL, 1),
(365294, 29622, 7969, '<td valign="top">i guess what makes this shot is the lighting on the building, it is a warm inviting golden. Also nice composition.    nice capture.</td>', 'i guess what makes this shot is the lighting on the building, it is a warm inviting golden. Also nice composition.    nice capture.', '2003-07-23 20:00:37.000000', NULL, 1),
(365295, 28890, 7969, '<td valign="top">Well, what i think is amazing about your shot is that this woman can stand like that.  Is she related to that little girl in the round challenge that could roll herself into a backwards circle?? (just kidding they look nothing alike).</td>', 'Well, what i think is amazing about your shot is that this woman can stand like that.  Is she related to that little girl in the round challenge that could roll herself into a backwards circle?? (just kidding they look nothing alike).', '2003-07-23 20:02:22.000000', NULL, 1),
(365374, 29723, 9146, '<td valign="top">ROTFLMAO</td>', 'ROTFLMAO', '2003-07-23 21:12:56.000000', NULL, 1),
(365377, 29094, 8637, '<td valign="top">My apologies Das...I got "fried" by someone for a somewhat similar capture where I also had a meaning that was not clearly seen by the viewer...guess I am just a bit over sensitive...your explanation means a lot and I by NO MEANS meant to offend...I did not take the time to evaluate your intent..please accept my apology and a new (elevated) vote!  And again...thanks, in more ways than one!</td>', 'My apologies Das...I got "fried" by someone for a somewhat similar capture where I also had a meaning that was not clearly seen by the viewer...guess I am just a bit over sensitive...your explanation means a lot and I by NO MEANS meant to offend...I did not take the time to evaluate your intent..please accept my apology and a new (elevated) vote!  And again...thanks, in more ways than one!', '2003-07-23 21:14:58.000000', NULL, 1),
(365440, 29768, 6888, '<td valign="top">inice job on the detail of the pen against the white background</td>', 'inice job on the detail of the pen against the white background', '2003-07-23 22:22:21.000000', NULL, 1),
