(367364, 29415, 6870, '<td valign="top">Not a contrast in technique or element, but in theme. The line of crosses is excellent and actually does contrast well with the random shapes all around the image.</td>', 'Not a contrast in technique or element, but in theme. The line of crosses is excellent and actually does contrast well with the random shapes all around the image.', '2003-07-26 15:32:38.000000', NULL, 1),
(367365, 29299, 6870, '<td valign="top">Lovely, simple, effective.</td>', 'Lovely, simple, effective.', '2003-07-26 15:32:55.000000', NULL, 1),
(367366, 29616, 6870, '<td valign="top">Light could be friendlier, but super contrasts and composition.</td>', 'Light could be friendlier, but super contrasts and composition.', '2003-07-26 15:33:24.000000', NULL, 1),
(367367, 29628, 6870, '<td valign="top">I personally wish this were darker, but what a super idea for contrasts! 9</td>', 'I personally wish this were darker, but what a super idea for contrasts! 9', '2003-07-26 15:33:54.000000', NULL, 1),
(367368, 29715, 6870, '<td valign="top">Super idea. Seems just a tad *muddy*. Perhaps more contrast would help with clarity? Perhaps whiter whites and blacker blacks? Hmmm. I love the composition and angle of framing.</td>', 'Super idea. Seems just a tad *muddy*. Perhaps more contrast would help with clarity? Perhaps whiter whites and blacker blacks? Hmmm. I love the composition and angle of framing.', '2003-07-26 15:35:06.000000', NULL, 1),
(367369, 29367, 6870, '<td valign="top">NIce contrast of lines here. I love the gritty feel to this.</td>', 'NIce contrast of lines here. I love the gritty feel to this.', '2003-07-26 15:35:28.000000', NULL, 1),
(367370, 29108, 6870, '<td valign="top">Super idea and execution. The joshua trees contrast so nicely with the fake trees (street lights). Silhouette works, too! 9</td>', 'Super idea and execution. The joshua trees contrast so nicely with the fake trees (street lights). Silhouette works, too! 9', '2003-07-26 15:37:21.000000', NULL, 1),
(367371, 29761, 6870, '<td valign="top">Nice abstract. The gradual minimalizing of the shapes keeps the image engaging. 9</td>', 'Nice abstract. The gradual minimalizing of the shapes keeps the image engaging. 9', '2003-07-26 15:38:16.000000', NULL, 1),
(367372, 29701, 6870, '<td valign="top">Fantastic use of negative space and composition. Just super. 10</td>', 'Fantastic use of negative space and composition. Just super. 10', '2003-07-26 15:38:41.000000', NULL, 1),
(367373, 29655, 6870, '<td valign="top">LIghting seems slightly harsh and unfriendly, but super idea of contrasting the pads with the green water.</td>', 'LIghting seems slightly harsh and unfriendly, but super idea of contrasting the pads with the green water.', '2003-07-26 15:39:09.000000', NULL, 1),
(367374, 28869, 6870, '<td valign="top">Harsh light seems intentional, so it works. Nice composition, too.</td>', 'Harsh light seems intentional, so it works. Nice composition, too.', '2003-07-26 15:39:41.000000', NULL, 1),
(367375, 29015, 6870, '<td valign="top">Amen to this photo!</td>', 'Amen to this photo!', '2003-07-26 15:39:58.000000', NULL, 1),
(367376, 29483, 6870, '<td valign="top">Weird, but in a good way. I wish the flower weren''t so bright that its detail is lost.</td>', 'Weird, but in a good way. I wish the flower weren''t so bright that its detail is lost.', '2003-07-26 15:40:43.000000', NULL, 1),
(367377, 29453, 6870, '<td valign="top">Fun stuff here. Title gives a delightful red herring. I love the contrasts between the snails circular lines against the square of the fencing. B/W and Color contrasts work well too. 9</td>', 'Fun stuff here. Title gives a delightful red herring. I love the contrasts between the snails circular lines against the square of the fencing. B/W and Color contrasts work well too. 9', '2003-07-26 15:41:51.000000', NULL, 1),
(367378, 29389, 6870, '<td valign="top">I wish I could see the fields of gold. I do like the contrasts here though, which makes that horse pop. 9</td>', 'I wish I could see the fields of gold. I do like the contrasts here though, which makes that horse pop. 9', '2003-07-26 15:42:30.000000', NULL, 1),
(367379, 29631, 6870, '<td valign="top">Lovely and interesting. My top so far! 10</td>', 'Lovely and interesting. My top so far! 10', '2003-07-26 15:44:06.000000', NULL, 1),
(367380, 29305, 6870, '<td valign="top">Good eye for finding contrasts in everyday things.</td>', 'Good eye for finding contrasts in everyday things.', '2003-07-26 15:44:30.000000', NULL, 1),
(367381, 29680, 6870, '<td valign="top">I love this shot. Very nice tones and colors.</td>', 'I love this shot. Very nice tones and colors.', '2003-07-26 15:45:01.000000', NULL, 1),
(367383, 29599, 6870, '<td valign="top">Tender and lovely. I find it very nice that the lines and textures of the hands are what give clues to the contrasts in age. Well duh, I guess (he said to himself!). Nice work. 10</td>', 'Tender and lovely. I find it very nice that the lines and textures of the hands are what give clues to the contrasts in age. Well duh, I guess (he said to himself!). Nice work. 10', '2003-07-26 15:46:18.000000', NULL, 1),
(367384, 29767, 6870, '<td valign="top">Nice use of negative space. The harsh light seems intentional and works for your theme nicely.</td>', 'Nice use of negative space. The harsh light seems intentional and works for your theme nicely.', '2003-07-26 15:46:57.000000', NULL, 1),
(367385, 29329, 6870, '<td valign="top">Cool shot! Works for me! 10</td>', 'Cool shot! Works for me! 10', '2003-07-26 15:47:18.000000', NULL, 1),
(367386, 29635, 6870, '<td valign="top">Super idea! I love the contrasts here and the negative space. Lighting seems a bit uninteresting, but your composition works wonders.</td>', 'Super idea! I love the contrasts here and the negative space. Lighting seems a bit uninteresting, but your composition works wonders.', '2003-07-26 15:48:12.000000', NULL, 1),
(367387, 29754, 6870, '<td valign="top">Very nice. The contrasts here make both leaves and bricks more interesting. 9</td>', 'Very nice. The contrasts here make both leaves and bricks more interesting. 9', '2003-07-26 15:48:47.000000', NULL, 1),
(367388, 29163, 6870, '<td valign="top">I''m not sure why,but I love the grain here. It gives a gritty feeling. Almost as if the flowers are a bright spot in a dingy world.</td>', 'I''m not sure why,but I love the grain here. It gives a gritty feeling. Almost as if the flowers are a bright spot in a dingy world.', '2003-07-26 15:49:42.000000', NULL, 1),
(367390, 29578, 6870, '<td valign="top">Nice pushing of the boundaries. This is a wonderful photograph that revels in its rebelliousness--and works. 10</td>', 'Nice pushing of the boundaries. This is a wonderful photograph that revels in its rebelliousness--and works. 10', '2003-07-26 15:50:40.000000', NULL, 1),
(367391, 29324, 6870, '<td valign="top">Really interesting use of lines here.</td>', 'Really interesting use of lines here.', '2003-07-26 15:50:58.000000', NULL, 1),
(367392, 29110, 6870, '<td valign="top">Really wonderful idea. The folds work wonderfully! It could be in sharper focus, which would have amplified your contrasts even more. Nice work.</td>', 'Really wonderful idea. The folds work wonderfully! It could be in sharper focus, which would have amplified your contrasts even more. Nice work.', '2003-07-26 15:52:18.000000', NULL, 1),
(367393, 29746, 6870, '<td valign="top">Sillhouette and sun work wonders here! Looks kinda like Wyoming!</td>', 'Sillhouette and sun work wonders here! Looks kinda like Wyoming!', '2003-07-26 15:53:19.000000', NULL, 1),
(367394, 29427, 6870, '<td valign="top">Super! I wish the flower had more light, but the contrasts are wonderful.</td>', 'Super! I wish the flower had more light, but the contrasts are wonderful.', '2003-07-26 15:54:03.000000', NULL, 1),
(367395, 29567, 6870, '<td valign="top">Contrast of theme instead of element, but I really enjoy how the textures contrast between the two vehicles.</td>', 'Contrast of theme instead of element, but I really enjoy how the textures contrast between the two vehicles.', '2003-07-26 15:54:52.000000', NULL, 1),
(367396, 29727, 6870, '<td valign="top">Makes me hungry! Nice work!</td>', 'Makes me hungry! Nice work!', '2003-07-26 15:55:13.000000', NULL, 1),
(367397, 29582, 6870, '<td valign="top">Clear contrasts and simple composition. Nice work. 9</td>', 'Clear contrasts and simple composition. Nice work. 9', '2003-07-26 15:56:26.000000', NULL, 1),
(367398, 28772, 6870, '<td valign="top">What a nifty idea! Lighting is perfect! 9</td>', 'What a nifty idea! Lighting is perfect! 9', '2003-07-26 15:57:31.000000', NULL, 1),
(367399, 29673, 6870, '<td valign="top">Face is a little dark, but the contrasts are communicated so clearly!</td>', 'Face is a little dark, but the contrasts are communicated so clearly!', '2003-07-26 15:58:00.000000', NULL, 1),
