(367401, 29544, 6870, '<td valign="top">Oh so subtle. I like it immensely! 9</td>', 'Oh so subtle. I like it immensely! 9', '2003-07-26 15:59:18.000000', NULL, 1),
(367402, 29749, 6870, '<td valign="top">Very interesting and dynamic. Super work. 9</td>', 'Very interesting and dynamic. Super work. 9', '2003-07-26 15:59:58.000000', NULL, 1),
(367403, 29335, 6870, '<td valign="top">Very high key--I''d like to see this a bit darker, but the lines and composition are wonderful.</td>', 'Very high key--I''d like to see this a bit darker, but the lines and composition are wonderful.', '2003-07-26 16:00:41.000000', NULL, 1),
(367404, 29753, 6870, '<td valign="top">Sure! I like! Very clearly communicated!</td>', 'Sure! I like! Very clearly communicated!', '2003-07-26 16:01:09.000000', NULL, 1),
