(367541, 29723, 8953, '<td valign="top">I see the contrast:) and for some this is a truth. but for others it is offensive. I had rated this a two the first go round but after revisting  I felt my judgement to harsh. what does not seem to be right, is the contrast with the bear, it seems to dark to me. what also seems inconsistant is the harsh light that is falling on the sex toy but it remains dull. over all the picture could be a little brighter. good luck 4</td>', 'I see the contrast:) and for some this is a truth. but for others it is offensive. I had rated this a two the first go round but after revisting  I felt my judgement to harsh. what does not seem to be right, is the contrast with the bear, it seems to dark to me. what also seems inconsistant is the harsh light that is falling on the sex toy but it remains dull. over all the picture could be a little brighter. good luck 4', '2003-07-26 22:06:11.000000', NULL, 1),
(367542, 29493, 8953, '<td valign="top">ok...first a good shot super contrast and i like the light falling on the cross. but what does not work for me is the title unless you meant to make another statement. the bird does not look like a bird of "PREY" which confuses the shot for me unless you meant to title it "PRAY" which would make more sense...I dont know:(  I will not as I know some may have take away because of the title, just kinda would like to know what meaning you meant. good luck 6</td>', 'ok...first a good shot super contrast and i like the light falling on the cross. but what does not work for me is the title unless you meant to make another statement. the bird does not look like a bird of "PREY" which confuses the shot for me unless you meant to title it "PRAY" which would make more sense...I dont know:(  I will not as I know some may have take away because of the title, just kinda would like to know what meaning you meant. good luck 6', '2003-07-26 22:15:28.000000', NULL, 1),
(367543, 29680, 8953, '<td valign="top">did not see alot of contrast in this shot...in another challenge this would have worked better for me.</td>', 'did not see alot of contrast in this shot...in another challenge this would have worked better for me.', '2003-07-26 22:17:24.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(367560, 29389, 4493, '<td valign="top">This is art museum ready. This image is so perfect. I like it all the way from the back lighting to the DOF used. Your back and white treatment is perfect. Excellent shot! 10 -danny</td>', 'This is art museum ready. This image is so perfect. I like it all the way from the back lighting to the DOF used. Your back and white treatment is perfect. Excellent shot! 10 -danny', '2003-07-27 00:00:45.000000', NULL, 1),
(367561, 29743, 7190, '<td valign="top">really nice photo but why is this a "contrast"? or do I have to know your model''s personality?</td>', 'really nice photo but why is this a "contrast"? or do I have to know your model''s personality?', '2003-07-27 00:01:15.000000', NULL, 1),
(367562, 29493, 4493, '<td valign="top">This was a great find. The dove perched on top of the cross with a heavenly cloud behind it is just excellent. The story this images tells is one of hope for those we lossed. This is truely a piece of art. 10 -danny</td>', 'This was a great find. The dove perched on top of the cross with a heavenly cloud behind it is just excellent. The story this images tells is one of hope for those we lossed. This is truely a piece of art. 10 -danny', '2003-07-27 00:02:13.000000', NULL, 1),
(367563, 29668, 4493, '<td valign="top">Subtle shades of light again the backdrop, the soft hazy purple and shape of the vase make for a truely wonderful shot. This is worthy of print in a gallery. 10 -danny</td>', 'Subtle shades of light again the backdrop, the soft hazy purple and shape of the vase make for a truely wonderful shot. This is worthy of print in a gallery. 10 -danny', '2003-07-27 00:03:27.000000', NULL, 1),
(367567, 29628, 4493, '<td valign="top">WOW! Spectacular view point. The grains of sand put me right there. The texture is remarkable. Nice shot! 10 -danny</td>', 'WOW! Spectacular view point. The grains of sand put me right there. The texture is remarkable. Nice shot! 10 -danny', '2003-07-27 00:04:40.000000', NULL, 1),
(367569, 29616, 4493, '<td valign="top">This is my top pic of the week. I love the story told in this picture. The two people being the sole riders and also being the only color object make for a great angle on contrast. Nice sharp image with great b/w treatment! 10 -danny</td>', 'This is my top pic of the week. I love the story told in this picture. The two people being the sole riders and also being the only color object make for a great angle on contrast. Nice sharp image with great b/w treatment! 10 -danny', '2003-07-27 00:06:50.000000', NULL, 1),
(367570, 28890, 4493, '<td valign="top">Purty Pitcher! :-)<br/> <br/>This woman is in great shape and the pose selected represents contrast nicely, that coupled with the b/w treatment give this image a top score! Nicely done! 10 -danny</td>', 'Purty Pitcher! :-) This woman is in great shape and the pose selected represents contrast nicely, that coupled with the b/w treatment give this image a top score! Nicely done! 10 -danny', '2003-07-27 00:08:10.000000', NULL, 1),
(367571, 29651, 4493, '<td valign="top">I want to take an image just like this! The tones and warmth of the light with the placement and shadow of the violin make this an excellent image. Great job! 9 -danny</td>', 'I want to take an image just like this! The tones and warmth of the light with the placement and shadow of the violin make this an excellent image. Great job! 9 -danny', '2003-07-27 00:09:24.000000', NULL, 1),
(367573, 29761, 4493, '<td valign="top">Simple and affective. The light and tones are wonderful! 9 -danny</td>', 'Simple and affective. The light and tones are wonderful! 9 -danny', '2003-07-27 00:10:09.000000', NULL, 1),
(367574, 29776, 4493, '<td valign="top">This image is a contrast on environment, not black and white. Many people may not get the image, but to me you are showing that all that glitters isn''t gold and that those with the money look down upon those without. I like this a lot! 9 -danny</td>', 'This image is a contrast on environment, not black and white. Many people may not get the image, but to me you are showing that all that glitters isn''t gold and that those with the money look down upon those without. I like this a lot! 9 -danny', '2003-07-27 00:11:40.000000', NULL, 1),
(367575, 29444, 2553, '<td valign="top">One of my favorites for this challenge, I really love the juxtaposition of the wonderful old stone architecture and the very modern building.  The colors work beautifully together, and your choice of composition works well to emphasize the tremendous difference.  I am so glad that you left it color!  Very nice shot!</td>', 'One of my favorites for this challenge, I really love the juxtaposition of the wonderful old stone architecture and the very modern building.  The colors work beautifully together, and your choice of composition works well to emphasize the tremendous difference.  I am so glad that you left it color!  Very nice shot!', '2003-07-27 00:12:44.000000', NULL, 1),
(367577, 29299, 4493, '<td valign="top">Print this and hang it somewhere in your house for all to see! This is truely a spectacular image with great warmth to it. I like how you included the foreground object to give depth to this image. Well done! 9 -danny</td>', 'Print this and hang it somewhere in your house for all to see! This is truely a spectacular image with great warmth to it. I like how you included the foreground object to give depth to this image. Well done! 9 -danny', '2003-07-27 00:12:52.000000', NULL, 1),
(367578, 29657, 4493, '<td valign="top">I love how you have used the natural surroundings to frame the sun. Your dark deep orange in contrast to the black structure makes for a visually appealing image. Good stuff! 9 -danny</td>', 'I love how you have used the natural surroundings to frame the sun. Your dark deep orange in contrast to the black structure makes for a visually appealing image. Good stuff! 9 -danny', '2003-07-27 00:14:04.000000', NULL, 1),
(367580, 29644, 4493, '<td valign="top">Unique! That helps overcome the darkness in the eyes. I think this is probably one of the most interesting images I''ve come across in a while. Not sure what it says to me, but I really like it. 9 -danny</td>', 'Unique! That helps overcome the darkness in the eyes. I think this is probably one of the most interesting images I''ve come across in a while. Not sure what it says to me, but I really like it. 9 -danny', '2003-07-27 00:15:27.000000', NULL, 1),
(367582, 29628, 2553, '<td valign="top">Just an incredible shot, and one of my 10''s for this challenge.  I love the way you composed the shot, and the repetition of the wavy lines moves the eye all through the photo.  Love the contrast of light/dark as well as small lines/large lines.  Good eye, and wonderful shot!</td>', 'Just an incredible shot, and one of my 10''s for this challenge.  I love the way you composed the shot, and the repetition of the wavy lines moves the eye all through the photo.  Love the contrast of light/dark as well as small lines/large lines.  Good eye, and wonderful shot!', '2003-07-27 00:16:13.000000', NULL, 1),
(367583, 29581, 7190, '<td valign="top">next time it would make for a more intresting photo to pull the objects farther away from the wall and maybe pull back a bit to see the bottoms of the vases.</td>', 'next time it would make for a more intresting photo to pull the objects farther away from the wall and maybe pull back a bit to see the bottoms of the vases.', '2003-07-27 00:16:14.000000', NULL, 1),
(367584, 29715, 4493, '<td valign="top">What makes this a nice piano shot is the texture in the keys! I have seen many a keys, but this one in it''s orientation and the texture bring this together to be a nice abstract piece of art. 9 -danny</td>', 'What makes this a nice piano shot is the texture in the keys! I have seen many a keys, but this one in it''s orientation and the texture bring this together to be a nice abstract piece of art. 9 -danny', '2003-07-27 00:16:27.000000', NULL, 1),
(367585, 29599, 4493, '<td valign="top">A classic pose and classic black and white treatment. This is an image that spans generations. Well done. 9 -danny</td>', 'A classic pose and classic black and white treatment. This is an image that spans generations. Well done. 9 -danny', '2003-07-27 00:17:12.000000', NULL, 1),
(367587, 29335, 2553, '<td valign="top">I''m guessing the "contrast" is simply in the texture of the tree, and maybe the tree against the white background as well.  Either way, I like this shot very much.  Composition leads the eye throughout the photo, the black and white works well, and I do like the "high key" approach.  This looks like a bonsai - (I really adore those, though cannot keep them alive) - great choice of subject.</td>', 'I''m guessing the "contrast" is simply in the texture of the tree, and maybe the tree against the white background as well.  Either way, I like this shot very much.  Composition leads the eye throughout the photo, the black and white works well, and I do like the "high key" approach.  This looks like a bonsai - (I really adore those, though cannot keep them alive) - great choice of subject.', '2003-07-27 00:20:30.000000', NULL, 1),
(367589, 29324, 2553, '<td valign="top">Absolutely lovin'' this shot!  PLEASE remind me to put it on my favorites!  I was a little surprised that you didn''t do black and white, but I am pleased that you did not - the color is wonderful, giving it that "beachy" feel.  I had given this a 9, but on viewing it again, (and again...) I am changing it to 10.  The lines, the curves, the terrific lights and darks all work to make this shot so appealing.</td>', 'Absolutely lovin'' this shot!  PLEASE remind me to put it on my favorites!  I was a little surprised that you didn''t do black and white, but I am pleased that you did not - the color is wonderful, giving it that "beachy" feel.  I had given this a 9, but on viewing it again, (and again...) I am changing it to 10.  The lines, the curves, the terrific lights and darks all work to make this shot so appealing.', '2003-07-27 00:23:38.000000', NULL, 1),
(367591, 28890, 2553, '<td valign="top">I like your contrast "concept" - both the circle/square and the light/dark.  I would have expected it to be a little more "high key", but all in all it works well in it''s simplicity.  Lovely shot.</td>', 'I like your contrast "concept" - both the circle/square and the light/dark.  I would have expected it to be a little more "high key", but all in all it works well in it''s simplicity.  Lovely shot.', '2003-07-27 00:26:17.000000', NULL, 1),
(367593, 29583, 2553, '<td valign="top">Good catch!  What are the odds of catching  a white one and a black one together like this??  Very appealing shot, I like the composition and the "black and white" treatment.  Would have liked the background to be a little more out of focus, but hey, you can''t have everything!</td>', 'Good catch!  What are the odds of catching  a white one and a black one together like this??  Very appealing shot, I like the composition and the "black and white" treatment.  Would have liked the background to be a little more out of focus, but hey, you can''t have everything!', '2003-07-27 00:28:47.000000', NULL, 1),
(367596, 29394, 2553, '<td valign="top">There were more color shots in "contrasts" than I expected, but none jumped out at me the way this one did!  It is just beautiful!  Every single thing from depth of field to color and composition are great.  Good eye and steady hand! This is a shot to be proud of.</td>', 'There were more color shots in "contrasts" than I expected, but none jumped out at me the way this one did!  It is just beautiful!  Every single thing from depth of field to color and composition are great.  Good eye and steady hand! This is a shot to be proud of.', '2003-07-27 00:32:52.000000', NULL, 1),
(367598, 29651, 2553, '<td valign="top">This shot just holds a certain appeal for me.  Rich color, the subject bleeding off into the negative space, the simple border, and your composition give it a kind of romantic, old-world feel.  Really a lovely shot.</td>', 'This shot just holds a certain appeal for me.  Rich color, the subject bleeding off into the negative space, the simple border, and your composition give it a kind of romantic, old-world feel.  Really a lovely shot.', '2003-07-27 00:36:39.000000', NULL, 1),
(367600, 29165, 2553, '<td valign="top">Can''t imagine why anyone would try to DQ this.   I''m a sucker for feathers, and this shot is very interesting.  I''m not entirely crazy about the border, but not grading down for it.  I like that the feathers look like they were just blown away and landed in a group; I like the somewhat "high-key" approach, and the way some of the feathers blend into the background.  .</td>', 'Can''t imagine why anyone would try to DQ this.   I''m a sucker for feathers, and this shot is very interesting.  I''m not entirely crazy about the border, but not grading down for it.  I like that the feathers look like they were just blown away and landed in a group; I like the somewhat "high-key" approach, and the way some of the feathers blend into the background.  .', '2003-07-27 00:40:22.000000', NULL, 1),
(367611, 29736, 1031, '<td valign="top">I like your choice to use B+W to focus on the contrasts, although I bet this looks pretty good in color as well.</td>', 'I like your choice to use B+W to focus on the contrasts, although I bet this looks pretty good in color as well.', '2003-07-27 01:07:47.000000', NULL, 1),
(367614, 29165, 1031, '<td valign="top">Personally, I like the border effect, but wish it ran all the way into the corners. Good exposure, focus.</td>', 'Personally, I like the border effect, but wish it ran all the way into the corners. Good exposure, focus.', '2003-07-27 01:14:15.000000', NULL, 1),
(367633, 29453, 1031, '<td valign="top">Just some slimy M&amp;M''s I guess.</td>', 'Just some slimy M&M''s I guess.', '2003-07-27 02:14:59.000000', NULL, 1),
(367635, 29483, 1031, '<td valign="top">Makes is look like a flower tossed into the La Brea Tar Pits; mighty tempting for some mastadon I guess. Certainly plenty of contrast here though!</td>', 'Makes is look like a flower tossed into the La Brea Tar Pits; mighty tempting for some mastadon I guess. Certainly plenty of contrast here though!', '2003-07-27 02:17:30.000000', NULL, 1),
(367638, 29663, 1031, '<td valign="top">Very nice mask--my mom would like this one!</td>', 'Very nice mask--my mom would like this one!', '2003-07-27 02:25:44.000000', NULL, 1),
(367641, 29288, 1031, '<td valign="top">My somewhat similar idea would have worked better with (hopefully) faux fur like this -- good job. Not sure about using two knives though, at least just displayed as they are. I think I''d either use just one, or have them on conflict or other more "dynamic" position.</td>', 'My somewhat similar idea would have worked better with (hopefully) faux fur like this -- good job. Not sure about using two knives though, at least just displayed as they are. I think I''d either use just one, or have them on conflict or other more "dynamic" position.', '2003-07-27 02:41:18.000000', NULL, 1),
(367642, 29582, 1031, '<td valign="top">You may have tied me for most "misleading" title with this ....</td>', 'You may have tied me for most "misleading" title with this ....', '2003-07-27 02:46:12.000000', NULL, 1),
(367675, 29761, 10629, '<td valign="top">Simple is best. I like it.</td>', 'Simple is best. I like it.', '2003-07-27 07:27:12.000000', NULL, 1),
(367698, 29335, 5728, '<td valign="top">Is this one of those bonzai trees? Good idea, the black and white was a good choice, the contrasts are much clearer.</td>', 'Is this one of those bonzai trees? Good idea, the black and white was a good choice, the contrasts are much clearer.', '2003-07-27 10:23:03.000000', NULL, 1),
