(368297, 29727, 472, '<td valign="top">vote per commenters, almost 9!  And a favorite!  Wow, i''m honored.  i guess i did a cult classic here.  Thanks, O commenters, for your unrelenting positivity.  It''s much appreciated down here at 37th place .. :)</td>', 'vote per commenters, almost 9!  And a favorite!  Wow, i''m honored.  i guess i did a cult classic here.  Thanks, O commenters, for your unrelenting positivity.  It''s much appreciated down here at 37th place .. :)', '2003-07-28 08:43:12.000000', NULL, 0),
(368307, 29663, 9679, '<td valign="top">I am thrilled that this shot did as well as it did. As a newbie, this is my first "serious" shot and I was fortunate to have an interesting subject on hand. Thanks to everyone for their comments and scores. The talent and creativity on DPC never ceases to amaze me and I am learning so much from all of you, as well as being continually inspired.<br/></td>', 'I am thrilled that this shot did as well as it did. As a newbie, this is my first "serious" shot and I was fortunate to have an interesting subject on hand. Thanks to everyone for their comments and scores. The talent and creativity on DPC never ceases to amaze me and I am learning so much from all of you, as well as being continually inspired.', '2003-07-28 08:58:05.000000', NULL, 0),
(368314, 29506, 917, '<td valign="top">Problems on the right side, mostly cos the pole is slightly convex (might be barrel/pincushion problems) but also cos the repeating elements of the left are absent on the right.<br/> <br/>Theres a few decent pics within the frame shown:<br/>The 45degree wire from the bottom left can unify the whole thing if you crop where it runs out in the top right.<br/>The repeating theme of the 60degree pole is also a good element to use. I think you''d need more on the left to make it work. You''d also need to crop some of the top and bottom, as well as the right side.<br/>The right side might be redeemed if you show the end of it, I.e. show empty sky on the right.<br/> <br/>Also, glass and steel dont make a good contrast, being both hrad and modern.<br/></td>', 'Problems on the right side, mostly cos the pole is slightly convex (might be barrel/pincushion problems) but also cos the repeating elements of the left are absent on the right. Theres a few decent pics within the frame shown:The 45degree wire from the bottom left can unify the whole thing if you crop where it runs out in the top right.The repeating theme of the 60degree pole is also a good element to use. I think you''d need more on the left to make it work. You''d also need to crop some of the top and bottom, as well as the right side.The right side might be redeemed if you show the end of it, I.e. show empty sky on the right. Also, glass and steel dont make a good contrast, being both hrad and modern.', '2003-07-28 09:01:44.000000', NULL, 0),
(368375, 29493, 10045, '<td valign="top">This is going in my favorites.  I think the title was well thought out.</td>', 'This is going in my favorites.  I think the title was well thought out.', '2003-07-28 09:56:08.000000', NULL, 0),
(368377, 29493, 806, '<td valign="top">excellent imagery and lighting. congrats on 3rd!</td>', 'excellent imagery and lighting. congrats on 3rd!', '2003-07-28 09:57:23.000000', NULL, 0),
(368390, 29599, 10145, '<td valign="top">Very cool! Old vs new, youth and age..love it...congrats on a well deserved ribbon and terrific photo!</td>', 'Very cool! Old vs new, youth and age..love it...congrats on a well deserved ribbon and terrific photo!', '2003-07-28 10:10:24.000000', NULL, 0),
(368392, 29493, 10145, '<td valign="top">Very cool shot! I like this..well done with the lighting as well...congrats on ribbon!</td>', 'Very cool shot! I like this..well done with the lighting as well...congrats on ribbon!', '2003-07-28 10:12:12.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(368408, 29599, 7763, '<td valign="top">Very nicely done... I had been toying with trying this but couldn''t find a child in time. well done, congrats</td>', 'Very nicely done... I had been toying with trying this but couldn''t find a child in time. well done, congrats', '2003-07-28 10:33:32.000000', NULL, 0),
(368416, 29761, 6651, '<td valign="top">This was my first entry into a challenge, although I''ve been a member for a number of months.  I had to hang these new blinds on Sunday (due to my Siberian Husky still being in her chewing stage) and just couldn''t pass up the perfect contrast presented in light of the current challenge.  I fear the simplicity of the shot didn''t ''speak'' to people, leading to the low score, but I am pretty happy with it.</td>', 'This was my first entry into a challenge, although I''ve been a member for a number of months.  I had to hang these new blinds on Sunday (due to my Siberian Husky still being in her chewing stage) and just couldn''t pass up the perfect contrast presented in light of the current challenge.  I fear the simplicity of the shot didn''t ''speak'' to people, leading to the low score, but I am pretty happy with it.', '2003-07-28 10:37:10.000000', NULL, 0),
(368442, 29299, 6696, '<td valign="top">Congratulations on coming this close - I am just an inch behind you!</td>', 'Congratulations on coming this close - I am just an inch behind you!', '2003-07-28 11:04:16.000000', NULL, 0),
(368446, 29682, 6696, '<td valign="top">Good showing Tim!  We both came soo close this time - I can almost smell a ribbon. :)</td>', 'Good showing Tim!  We both came soo close this time - I can almost smell a ribbon. :)', '2003-07-28 11:09:37.000000', NULL, 0),
(368452, 28890, 714, '<td valign="top">This is the coolest shot! I love the pose. Excellent contrast.  Did you mess with you exposure settings at all?  I would love to see her dance.</td>', 'This is the coolest shot! I love the pose. Excellent contrast.  Did you mess with you exposure settings at all?  I would love to see her dance.', '2003-07-28 11:12:41.000000', NULL, 0),
